/**
 * The client's key list mirrors the server catalogue. shared/permission-keys.json
 * is regenerated by a backend test from app/services/permissions.py, so a key
 * added, renamed or removed on either side fails here — and so does a shipped
 * default that the test fixtures (permissionFixtures.ts) no longer match.
 */
import { describe, it, expect } from 'vitest';
import catalogue from '../../../../shared/permission-keys.json';
import { APPROVABLE_KEYS, PERMISSION_KEYS, PM_BUNDLE } from '@/types/permissions';
import { SUPERUSER_DEFAULTS, USER_DEFAULTS } from '@/test/permissionFixtures';

const sorted = (keys: Iterable<string>) => [...keys].sort();

describe('permission catalogue mirror', () => {
  it('names exactly the server keys', () => {
    expect(sorted(PERMISSION_KEYS)).toEqual(sorted(catalogue.keys));
    expect(new Set(PERMISSION_KEYS).size).toBe(PERMISSION_KEYS.length);
  });

  it('marks the same keys approvable', () => {
    expect(sorted(APPROVABLE_KEYS)).toEqual(sorted(catalogue.approvable));
  });

  it('uses the same project-manager bundle', () => {
    expect(sorted(PM_BUNDLE)).toEqual(sorted(catalogue.pm_bundle));
  });

  it('gives the fixtures the shipped default allow keys of each system role', () => {
    expect(new Set(SUPERUSER_DEFAULTS)).toEqual(new Set(catalogue.defaults.superuser));
    expect(new Set(USER_DEFAULTS)).toEqual(new Set(catalogue.defaults.user));
    expect(SUPERUSER_DEFAULTS).toHaveLength(new Set(SUPERUSER_DEFAULTS).size);
    expect(USER_DEFAULTS).toHaveLength(new Set(USER_DEFAULTS).size);
  });

  it('ships no approval-mode default the fixtures would miss', () => {
    // The fixtures model allow keys only (approval_required stays empty).
    expect('approval' in catalogue).toBe(false);
  });
});
